1060	    fn verify_accepts_valid_records() {
1061	        let key = "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b";
1062	        // Zero fields vs one empty field are both valid and distinct.
1063	        assert!(matches!(
1064	            verify_input(record_for(key, "id", 1, &[]).as_bytes(), key),
1065	            VerifyOutcome::Valid
1066	        ));
1067	        assert!(matches!(
1068	            verify_input(record_for(key, "id", 1, &[""]).as_bytes(), key),
1069	            VerifyOutcome::Valid
1070	        ));
1071	        // Unicode, duplicate and reordered fields.
1072	        let rec = record_for(key, "demo", 3, &["hello", "世界", "世界"]);
1073	        assert!(matches!(verify_input(rec.as_bytes(), key), VerifyOutcome::Valid));
1074	        // Surrounding JSON whitespace and internal reformatting are fine.
1075	        let pretty = format!(
1076	            " \n\t{}  \r\n",
1077	            rec.replace(',', ",\n  ").replace('{', "{\n  ")
1078	        );
1079	        assert!(matches!(
1080	            verify_input(pretty.as_bytes(), key),
1081	            VerifyOutcome::Valid
1082	        ));
1083	        // Member order must not matter.
1084	        let reordered = "{\"tag\":\"X\",\"fields\":[],\"key_version\":1,\"key_id\":\"id\",\
1085	                         \"algorithm\":\"HMAC-SHA256\",\"format\":1}";
1086	        // Recompute with the real tag to keep this a positive case.
1087	        let mut reordered = reordered.to_string();
1088	        let tag = sign_tag(key, "id", 1, &[]);
1089	        reordered = reordered.replace('X', &tag);
1090	        assert!(matches!(
1091	            verify_input(reordered.as_bytes(), key),
