    /// Canonical decimal text: an optional '-' followed by digits with no
    /// leading zero ("0" and "-0" are the only spellings containing '0' up
    /// front; JSON allows "-0").
    text: String,
    /// The parsed value when it fits in `i128`, otherwise `None`.
    value: Option<i128>,
    /// Number of decimal digits after the optional sign, without leading
    /// zeros ("0" has magnitude width 1).
    magnitude_width: usize,
    negative: bool,
}

impl IntLiteral {
    fn from_text(text: &str) -> IntLiteral {
        let negative = text.starts_with('-');
        let digits = text.trim_start_matches('-');
        let magnitude_width = digits.len();
        IntLiteral {
            text: text.to_string(),
            value: text.parse::<i128>().ok(),
            magnitude_width,
            negative,
        }
    }

    /// Whether the integer equals `n`. Holds regardless of magnitude: a
    /// huge positive literal never compares equal to a small fixed value.
    fn is(&self, n: i128) -> bool {
        self.value == Some(n)
    }

