/// key-version range), where the error can name the actual rule,
/// instead of the parser rejecting well-formed JSON as "out of range".
fn parse_number(&mut self) -> Result<JsonValue, String> {
    let start = self.pos;
    if self.peek() == Some(b'-') {
        self.pos += 1;
    }
    match self.peek() {
        Some(b'0') => {
            self.pos += 1;
