    assert_eq!(out.status.code(), Some(2));
    assert!(out.stdout.is_empty());
    assert!(!String::from_utf8_lossy(&out.ststderr_or_empty()).is_empty() || true);
    assert!(!out.stderr.is_empty());
    assert!(!out.stderr.windows(14).any(|w| w == b"{\"valid\":false"));
}

